import hashlib,json,os,resource,subprocess,sys,time
from pathlib import Path
root=Path.cwd(); output=Path('/tmp/hcsn-3b20-final-validation-v1'); output.mkdir(exist_ok=False)
def identity(p):
 b=p.read_bytes();return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
inputs={str(p.relative_to(root)):identity(p) for p in sorted((root/'proposals/hcsn_persistence_v1').glob('*.py'))}
(output/'INPUTS.json').write_text(json.dumps(inputs,sort_keys=True,indent=2)+'\n')
commands=[['-m','unittest','-v','proposals.hcsn_persistence_v1.test_atomic_io','proposals.hcsn_persistence_v1.test_journal','proposals.hcsn_persistence_v1.test_materialize','proposals.hcsn_persistence_v1.test_runtime'],['-m','proposals.hcsn_persistence_v1.materialize','--output',str(output/'successor')],['proposals/hcsn_persistence_v1/test_successor_terminal.py','--successor',str(output/'successor')],['proposals/hcsn_persistence_v1/run_successor_tests.py','--successor',str(output/'successor')]]
rows=[];started=time.monotonic()
for i,args in enumerate(commands):
 before=time.monotonic();u=resource.getrusage(resource.RUSAGE_CHILDREN)
 result=subprocess.run([sys.executable,'-B',*args],capture_output=True,text=True)
 v=resource.getrusage(resource.RUSAGE_CHILDREN)
 (output/f'{i}.stdout').write_text(result.stdout);(output/f'{i}.stderr').write_text(result.stderr)
 print(f'COMMAND {i} RETURN {result.returncode}\n'+result.stdout+result.stderr,flush=True)
 rows.append({'command':args,'returncode':result.returncode,'wall_seconds':time.monotonic()-before,'child_cpu_seconds':(v.ru_utime+v.ru_stime)-(u.ru_utime+u.ru_stime),'stdout':identity(output/f'{i}.stdout'),'stderr':identity(output/f'{i}.stderr')})
 if result.returncode: break
unchanged=inputs=={name:identity(root/name) for name in inputs}
report={'schema':'hcsn-persistence-native-validation-v1','python':sys.version,'executable':sys.executable,'source_inputs':inputs,'source_unchanged':unchanged,'commands':rows,'commands_all_executed':len(rows)==4,'all_passed':len(rows)==4 and all(r['returncode']==0 for r in rows) and unchanged,'wall_seconds_through_report_lower_bound':time.monotonic()-started,'peak_children_rss_bytes':resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss*1024,'energy_joules':None,'scope':'synthetic software tests only; no original training resumed'}
(output/'RESULT.json').write_text(json.dumps(report,sort_keys=True,indent=2)+'\n');print('FINAL_RESULT '+json.dumps(report,sort_keys=True),flush=True)
raise SystemExit(0 if report['all_passed'] else 1)
